def priority(task, state, k=1.0, m=3.0, guard=0.25, eps=1e-6):
    # ATC urgency plus tenant tier, with a soft SLO guard that boosts
    # requests whose remaining slack is small relative to their estimate.
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / max(task.estimated_runtime, eps) * math.exp(
        -slack / (k * max(state.mean_est, eps))
    )
    # Guard: if slack is less than a fraction of estimated runtime, escalate.
    if slack <= guard * max(task.estimated_runtime, eps):
        atc *= 1.0 + (guard * max(task.estimated_runtime, eps) - slack) / max(
            guard * max(task.estimated_runtime, eps), eps
        )
    return tier * atc  # tuned (k=0.595,m=1.4,guard=0.104,eps=2.71e-06)

