def priority(task, state, c=1.0, m=3.0, k=0.5, s=1.0, q=0.5):
    ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    guard = 1e6 if ratio >= c else 0.0
    tier = m if task.tenant == 'premium' else 1.0
    est = max(task.estimated_runtime, 1e-6)
    scale = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    pressure = state.queue_work / max(state.capacity, 1e-6)
    if slack <= 0.0:
        risk = 1.0 + s * (-slack) / est
    else:
        risk = math.exp(-slack / (k * scale))
    if pressure > q:
        risk *= 1.0 + pressure
    return guard + tier * task.weight / est * risk  # tuned (c=2.58,m=0.944,k=1.59,s=0.299,q=0.853)

def priority(task, state, m=2.0, c=0.25, b=1.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    # Tiered lateness penalty approximation: the penalty jumps at
    # 0.25x and 1x estimate lateness. Approaching those thresholds
    # should cause a strong priority jump.
    lateness = wait + est - (task.due - task.release)
    if lateness <= 0:
        return tier / est
    if lateness <= c * est:
        return b * tier / est + 1.0 / est
    if lateness <= est:
        return 1e3 + b * tier / est
    return 1e6 + tier / est  # tuned (m=1.09,c=0.654,b=1.03)

