def priority(task, state, k=0.5, m=3.0, c=1.5, d=0.5):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    lateness = state.now + est - task.due
    if lateness <= 0.25 * est:
        penalty = 1.0
    elif lateness <= est:
        penalty = 3.0
    else:
        penalty = 10.0
    risk = penalty / est
    wait = state.now - task.release
    age = 1.0 + c * min(wait / est, d)
    return tier * atc * (1.0 + risk) * age  # tuned (k=0.157,m=9.56,c=0.448,d=0.853)

def priority(task, state, k=0.5, m=3.0, b=1.0, c=0.5):
