def priority(task, state, k=0.5, m=3.0, q_thresh=0.7, premium_urgent_boost=1.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wait = state.now - task.release
    aging = 1.0 + wait / max(task.estimated_runtime, 1e-6)
    congestion = min(1.0, state.queue_work / max(state.capacity, 1e-6))
    base = atc * (1.0 + (aging - 1.0) * congestion / max(q_thresh, 1e-6))
    if task.tenant == 'premium':
        projected_late = state.now + task.estimated_runtime - task.due
        if projected_late > 0:
            base *= premium_urgent_boost * (1.0 + projected_late / max(task.estimated_runtime, 1e-6))
    return base  # tuned (k=0.232,m=1.54,q_thresh=0.819,premium_urgent_boost=0.595)

def priority(task, state, k=0.5, m=3.0, guard=1.0):
    slack = task.due - task.estimated_runtime - state.now
    tier = m if task.tenant == 'premium' else 1.0
    if slack <= 0:
        return 1e6 * tier + 1.0 / max(task.estimated_runtime, 1e-6)
    wait_ratio = (state.now - task.release) / max(task.estimated_runtime, 1e-6)
    age = 1.0 + guard * wait_ratio
    return tier * age / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

